// Slug-to-ID mapping (populated at import time)
// Uses NFR_METADATA for slug resolution - import separately if needed

/**
 * Get NFR content by slug
 */
export function getNFRContent(slug: string): NFRSection | null {
  // Try direct slug match from slug mapping
  const id = SLUG_TO_ID[slug];
  if (id !== undefined) {
    return NFR_CONTENT_BY_ID[id] || null;
  }
  return null;
}

/**
 * Get NFR content by ID
 */
export function getNFRContentById(id: number): NFRSection | null {
  return NFR_CONTENT_BY_ID[id] || null;
}

// Slug-to-ID mapping
const SLUG_TO_ID: Record<string, number> = {};

// Initialize slug mapping from NFR_METADATA
import { NFR_METADATA } from './nfr-data';
for (const nfr of NFR_METADATA) {
  SLUG_TO_ID[nfr.slug] = nfr.id;
}
